            self.r=max(0,min(self.rows-1,row)); self.c=max(0,min(self.cols-1,col))
        elif final=='A': self.r=max(0,self.r-(vals[0] or 1 if vals else 1))
        elif final=='B': self.r=min(self.rows-1,self.r+(vals[0] or 1 if vals else 1))
        elif final=='C': self.c=min(self.cols-1,self.c+(vals[0] or 1 if vals else 1))
        elif final=='D': self.c=max(0,self.c-(vals[0] or 1 if vals else 1))
        elif final=='K':
            mode=vals[0] if vals else 0
            if mode==0: self.clear_eol()
        elif final=='J':
            # rough clear screen
            mode=vals[0] if vals else 0
            if mode in (0,2):
                for rr in range(self.rows):
                    for cc in range(self.cols): self.grid[rr][cc]=' '
    def feed(self,data):
