                i+=1; continue
            elif ch=='\b':
                self.c=max(0,self.c-1); i+=1; continue
            else:
                if ord(ch)>=32 or ch=='\n' or ch=='\r': self.put(ch)
                i+=1
    def text(self): return [''.join(r) for r in self.grid]

def read_all(master, quiet=0.05, max_time=1.0):
    data=b''; deadline=time.time()+max_time; last=time.time()
    while True:
        timeout=max(0, min(deadline-time.time(), quiet-(time.time()-last)))
        if timeout<=0: break
        r,_,_=select.select([master],[],[],timeout)
        if r:
            try: c=os.read(master,8192)
            except OSError: break
            if not c: break
            data+=c; last=time.time()
        if time.time()>=deadline: break
    return data

def run(args, actions, rows=24, cols=80):
    master,slave=pty.openpty(); fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack('HHHH',rows,cols,0,0))
