def printable_error(e: BaseException) -> str:
    if isinstance(e, UnicodeDecodeError):
        return "stream did not contain valid UTF-8"
    err = getattr(e, 'errno', None)
    if err is None and getattr(e, 'args', None):
        if isinstance(e.args[0], int): err = e.args[0]
    if err is not None:
        return f"{os.strerror(err)} (os error {err})"
    return str(e)


def char_width(ch: str, col: int = 0) -> int:
    if ch == '\t':
        return 8 - (col % 8)
    if not ch:
        return 0
    if unicodedata.combining(ch):
        return 0
    cat = unicodedata.category(ch)
    if cat.startswith('C'):
        return 0
    return 2 if unicodedata.east_asian_width(ch) in ('W','F') else 1


def str_width(s: str) -> int:
    col = 0
    for ch in s:
        col += char_width(ch, col)
    return col


def truncate_to_width(s: str, width: int) -> str:
    out=[]; col=0
    for ch in s:
        w=char_width(ch, col)
        if col + w > width: break
        out.append(ch); col += w
    return ''.join(out)


def pad_to_width(s: str, width: int) -> str:
    w = str_width(s)
    if w > width:
        return truncate_to_width(s, width)
    return s + ' ' * (width - w)


def row_cx_to_rx(row: str, cx: int) -> int:
    rx=0
    for ch in row[:max(0, min(cx, len(row)))]:
        rx += char_width(ch, rx)
    return rx


def rx_to_cx(row: str, rx_target: int) -> int:
    rx=0
    for i,ch in enumerate(row):
        w=char_width(ch, rx)
        if rx + w > rx_target:
            return i
        rx += w
    return len(row)


def syntax_for_filename(filename: Optional[str]) -> str:
    if not filename: return 'plain'
    base = filename.rsplit('/',1)[-1]
    ext = ''
    if '.' in base:
        ext = base.rsplit('.',1)[1].lower()
    if ext in ('rs',): return 'rust'
    if ext in ('c','h'): return 'c'
    if ext in ('cpp','cc','cxx','hpp','hh','hxx'): return 'c++'
    if ext == 'py': return 'python'
    if ext == 'go': return 'go'
    if ext == 'js': return 'javascript'
    return 'plain'


