def compute_syntax_colors(line: str, syntax: str) -> List[Optional[str]]:
    n=len(line); colors=[None]*n
    if syntax == 'plain':
        return colors
    i=0
    comment_started=False
    # comments and strings first
    while i<n:
        if syntax == 'python' and line[i] == '#':
            for j in range(i,n): colors[j]=GRAY
            break
        if syntax != 'python' and i+1<n and line[i:i+2] == '//':
            for j in range(i,n): colors[j]=GRAY
            break
        if syntax != 'python' and i+1<n and line[i:i+2] == '/*':
            j=i+2
            while j<n and not (j+1<n and line[j:j+2]=='*/'):
                j+=1
            j = min(n, j+2 if j<n else n)
            for k in range(i,j): colors[k]=GRAY
            i=j; continue
        if line[i] in ('"', "'"):
            quote=line[i]; j=i+1; esc=False
            while j<n:
                if esc:
                    esc=False
                elif line[j] == '\\':
                    esc=True
                elif line[j] == quote:
                    j+=1; break
                j+=1
            for k in range(i,min(j,n)): colors[k]=GREEN
            i=max(j,i+1); continue
        i+=1
    # words/numbers
    i=0; prev_decl=False
    decl=DECL.get(syntax,set()); ctrl=CONTROL.get(syntax,set()); typ=TYPES.get(syntax,set()); const=CONSTS.get(syntax,set())
    while i<n:
        if colors[i] is not None:
            i+=1; continue
        ch=line[i]
        if ch.isdigit() and (i==0 or not (line[i-1].isalnum() or line[i-1]=='_')):
            j=i+1
            while j<n and (line[j].isalnum() or line[j] in '._'):
                j+=1
            for k in range(i,j):
                if colors[k] is None: colors[k]=MAGENTA
            i=j; prev_decl=False; continue
        if ch.isalpha() or ch == '_':
            j=i+1
            while j<n and (line[j].isalnum() or line[j]=='_'):
                j+=1
            word=line[i:j]
            col=None
            if prev_decl:
                col=NAME
            if word in decl:
                col=BLUE; prev_decl=True
            elif word in ctrl:
                col=RED; prev_decl=False
            elif word in typ:
                col=YELLOW; prev_decl=False
            elif word in const:
                col=MAGENTA; prev_decl=False
            else:
                # in C, primitive types are yellow and do not mark next name. Other languages highlight first identifier after decl only.
                if word.strip():
                    # keep prev_decl through whitespace only; encountering any non-highlighted word consumes it
                    prev_decl=False
            if col:
                for k in range(i,j):
                    if colors[k] is None: colors[k]=col
            i=j; continue
        if not ch.isspace():
            # punctuation does not consume declaration for function name after 'fn ' but does after name
            pass
        i+=1
    return colors


def find_all_matches(rows: List[str], query: str) -> List[Tuple[int,int,int]]:
    if not query: return []
    out=[]; qlen=len(query)
    for y,row in enumerate(rows):
        start=0
        while True:
            idx=row.find(query,start)
            if idx<0: break
            out.append((y,idx,idx+qlen))
            start=idx+max(1,qlen)
    return out


@dataclass
class Buffer:
    filename: Optional[str]
    rows: List[str]
    empty_total_one: bool = False
    virgin: bool = False
    cx: int = 0
    cy: int = 0
    rowoff: int = 0
    coloff: int = 0
    last_edit: Optional[str] = None
    syntax: str = field(init=False)
    history: List[Tuple[List[str],int,int,bool]] = field(default_factory=list)
    hist_pos: int = 0
    saved_pos: int = 0

    def __post_init__(self):
        self.syntax = syntax_for_filename(self.filename)
        self.history = [(list(self.rows), self.cx, self.cy, self.empty_total_one)]
        self.hist_pos = 0
        self.saved_pos = 0

    def total_lines(self) -> int:
        return len(self.rows) if self.rows else (1 if self.empty_total_one else 0)

    def dirty(self) -> bool:
        return self.hist_pos != self.saved_pos

    def current_line_len(self) -> int:
        if 0 <= self.cy < len(self.rows): return len(self.rows[self.cy])
        return 0

    def current_rx(self) -> int:
        if 0 <= self.cy < len(self.rows):
            return row_cx_to_rx(self.rows[self.cy], self.cx)
        return 0

    def clamp_cursor(self):
        if self.cy < 0: self.cy=0
        if self.cy > len(self.rows): self.cy=len(self.rows)
        if self.cy < len(self.rows):
            if self.cx > len(self.rows[self.cy]): self.cx=len(self.rows[self.cy])
        else:
            self.cx=0
        if self.cx < 0: self.cx=0

    def snapshot(self):
        return (list(self.rows), self.cx, self.cy, self.empty_total_one)

    def restore(self, snap):
        self.rows=list(snap[0]); self.cx=snap[1]; self.cy=snap[2]; self.empty_total_one=snap[3]
        self.clamp_cursor(); self.last_edit=None

    def record_change(self, group: Optional[str]=None):
        self.virgin=False
        snap=self.snapshot()
        if self.hist_pos < len(self.history)-1:
            self.history = self.history[:self.hist_pos+1]
        if group and self.last_edit == group and self.hist_pos == len(self.history)-1:
            self.history[self.hist_pos] = snap
        else:
            # avoid duplicate snapshots
            if self.history and self.history[self.hist_pos] == snap:
                pass
            else:
                self.history.append(snap); self.hist_pos=len(self.history)-1
        self.last_edit=group

    def ensure_line_for_insert(self):
        if self.cy > len(self.rows): self.cy=len(self.rows)
        while self.cy >= len(self.rows):
            self.rows.append('')
        if self.empty_total_one and self.rows:
            self.empty_total_one=False

    def insert_char(self, ch: str):
        self.ensure_line_for_insert()
        row=self.rows[self.cy]
        self.cx=max(0,min(self.cx,len(row)))
        self.rows[self.cy]=row[:self.cx]+ch+row[self.cx:]
        self.cx+=1
        self.record_change('insert')

    def insert_newline(self):
        self.virgin=False
        if self.cy >= len(self.rows):
            self.rows.append('')
            self.cy=len(self.rows)-1; self.cx=0
        row=self.rows[self.cy]
        self.cx=max(0,min(self.cx,len(row)))
        self.rows[self.cy]=row[:self.cx]
        self.rows.insert(self.cy+1, row[self.cx:])
        self.cy+=1; self.cx=0
        if self.empty_total_one: self.empty_total_one=False
        self.record_change('newline')
        self.last_edit=None

    def backspace(self):
        if not self.rows:
            return False
        if self.cy > len(self.rows): self.cy=len(self.rows)
        if self.cy == len(self.rows):
            # EOF pseudo-line: move to end of last real line
            if self.cy>0:
                self.cy-=1; self.cx=len(self.rows[self.cy])
                return False
        if self.cx > 0:
            row=self.rows[self.cy]
            self.rows[self.cy]=row[:self.cx-1]+row[self.cx:]
            self.cx-=1
            self.record_change('delete')
            return True
        if self.cy > 0:
            prev_len=len(self.rows[self.cy-1])
            self.rows[self.cy-1]+=self.rows[self.cy]
            del self.rows[self.cy]
            self.cy-=1; self.cx=prev_len
            self.record_change('delete')
            return True
        return False

    def delete_forward(self):
        if self.cy >= len(self.rows): return False
        row=self.rows[self.cy]
        if self.cx < len(row):
            self.rows[self.cy]=row[:self.cx]+row[self.cx+1:]
            self.record_change('delete')
            return True
        if self.cy+1 < len(self.rows):
            self.rows[self.cy]+=self.rows[self.cy+1]
            del self.rows[self.cy+1]
            self.record_change('delete')
            return True
        return False

    def delete_to_eol(self):
        if self.cy >= len(self.rows): return False
        row=self.rows[self.cy]
        if self.cx < len(row):
            self.rows[self.cy]=row[:self.cx]
            self.record_change('delete')
            return True
        if self.cy+1 < len(self.rows):
            self.rows[self.cy]+=self.rows[self.cy+1]
            del self.rows[self.cy+1]
            self.record_change('delete')
            return True
        return False

    def delete_to_bol(self):
        if self.cy >= len(self.rows) or self.cx <= 0: return False
        row=self.rows[self.cy]
        self.rows[self.cy]=row[self.cx:]
        self.cx=0
        self.record_change('delete')
        return True

    def delete_word(self):
        if self.cy >= len(self.rows): return False
        if self.cx == 0:
            return self.backspace()
        row=self.rows[self.cy]
        pos=self.cx
        # delete preceding whitespace first, then a non-whitespace run
        while pos>0 and row[pos-1].isspace():
            pos-=1
        while pos>0 and not row[pos-1].isspace():
            pos-=1
        if pos != self.cx:
            self.rows[self.cy]=row[:pos]+row[self.cx:]
            self.cx=pos
            self.record_change('delete')
            return True
        return False

    def move_left(self):
        if self.cx>0:
            self.cx-=1
        elif self.cy>0:
            self.cy-=1; self.cx=len(self.rows[self.cy]) if self.cy < len(self.rows) else 0
        self.last_edit=None

    def move_right(self):
        if self.cy < len(self.rows):
            if self.cx < len(self.rows[self.cy]):
                self.cx+=1
            else:
                self.cy+=1; self.cx=0
        self.last_edit=None

    def move_up(self):
        if self.cy>0: self.cy-=1
        self.clamp_cursor(); self.last_edit=None

    def move_down(self):
        if self.cy < len(self.rows): self.cy+=1
        self.clamp_cursor(); self.last_edit=None

    def move_home(self):
        self.cx=0; self.last_edit=None

    def move_end(self):
        self.cx=len(self.rows[self.cy]) if self.cy < len(self.rows) else 0; self.last_edit=None

    def move_top(self):
        self.cy=0; self.cx=0; self.last_edit=None

    def move_bottom(self):
        self.cy=len(self.rows); self.cx=0; self.last_edit=None

    def move_next_word(self):
        if self.cy >= len(self.rows): return
        row=self.rows[self.cy]; n=len(row); i=self.cx
        if i<n and (row[i].isalnum() or row[i]=='_'):
            while i<n and (row[i].isalnum() or row[i]=='_'): i+=1
        while i<n and not (row[i].isalnum() or row[i]=='_'): i+=1
        if i>=n and self.cy < len(self.rows)-1:
            self.cy+=1; self.cx=0
        else:
            self.cx=i
        self.last_edit=None

    def move_prev_word(self):
        if self.cy >= len(self.rows):
            if self.rows: self.cy=len(self.rows)-1; self.cx=len(self.rows[self.cy])
            return
        row=self.rows[self.cy]; i=self.cx
        if i==0 and self.cy>0:
            self.cy-=1; self.cx=len(self.rows[self.cy]); row=self.rows[self.cy]; i=self.cx
        while i>0 and not (row[i-1].isalnum() or row[i-1]=='_'): i-=1
        while i>0 and (row[i-1].isalnum() or row[i-1]=='_'): i-=1
        self.cx=i; self.last_edit=None

    def move_next_paragraph(self):
        n=len(self.rows); y=self.cy
        while y<n and self.rows[y].strip()!='': y+=1
        while y<n and self.rows[y].strip()=='': y+=1
        if y<n: self.cy=y; self.cx=0
        else: self.move_bottom()
        self.last_edit=None

    def move_prev_paragraph(self):
        y=min(self.cy-1, len(self.rows)-1)
        while y>0 and self.rows[y].strip()=='': y-=1
        while y>0 and self.rows[y-1].strip()!='': y-=1
        # if immediately before current paragraph there is a blank, find the start after previous blank
        self.cy=max(0,y); self.cx=0; self.last_edit=None

    def undo(self) -> bool:
        if self.hist_pos <= 0: return False
        self.hist_pos-=1; self.restore(self.history[self.hist_pos]); return True

    def redo(self) -> bool:
        if self.hist_pos >= len(self.history)-1: return False
        self.hist_pos+=1; self.restore(self.history[self.hist_pos]); return True


def load_file(path: str) -> Buffer:
    try:
        with open(path, 'rb') as f:
            data=f.read()
    except FileNotFoundError:
        return Buffer(path, [''], empty_total_one=False, virgin=False)
    text=data.decode('utf-8')
    if text == '':
        rows=[]
    else:
        parts=text.split('\n')
        if parts and parts[-1]=='':
            parts=parts[:-1]
        rows=parts
    return Buffer(path, rows, empty_total_one=False, virgin=False)


class Terminal:
    def __init__(self):
        self.fd_in=sys.stdin.fileno(); self.fd_out=sys.stdout.fileno(); self.orig=None; self.raw=False; self.alt=False
    def setup(self) -> Tuple[int,int]:
        try:
            self.orig = termios.tcgetattr(self.fd_in)
        except termios.error as e:
            raise OSError(25, os.strerror(25))
        try:
            data=fcntl.ioctl(self.fd_out, termios.TIOCGWINSZ, struct.pack('HHHH',0,0,0,0))
        except OSError as e:
            data=fcntl.ioctl(self.fd_in, termios.TIOCGWINSZ, struct.pack('HHHH',0,0,0,0))
        rows, cols, _, _ = struct.unpack('HHHH', data)
        if rows < 3 or cols < 1:
            raise RuntimeError(f"Screen {cols}x{rows} is too small. At least 1x3 is necessary in width x height")
        return rows, cols
    def enable_raw(self):
        if self.orig is None: return
        raw=termios.tcgetattr(self.fd_in)
        raw[0] &= ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
        raw[1] &= ~(termios.OPOST)
        raw[2] |= termios.CS8
        raw[3] &= ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
        raw[6][termios.VMIN]=0
        raw[6][termios.VTIME]=1
        termios.tcsetattr(self.fd_in, termios.TCSAFLUSH, raw)
        self.raw=True
    def restore(self):
        if self.raw and self.orig is not None:
            try: termios.tcsetattr(self.fd_in, termios.TCSAFLUSH, self.orig)
            except Exception: pass
            self.raw=False
    def enter_alt(self):
        cwrite('\x1b[?1049h'); self.alt=True
    def leave_alt(self):
        if self.alt:
            cwrite('\x1b[?1049l\x1b[H'); self.alt=False
    def read_byte(self, timeout: Optional[float]=None) -> Optional[bytes]:
        if timeout is None:
            while True:
                try:
                    b=os.read(self.fd_in,1)
                except BlockingIOError:
                    b=b''
                if b: return b
                select.select([self.fd_in],[],[],0.05)
        else:
            r,_,_=select.select([self.fd_in],[],[],timeout)
            if not r: return None
            b=os.read(self.fd_in,1)
            return b or None

    def read_key(self):
        b=self.read_byte(None)
        if b is None: return UNKNOWN
        c=b[0]
        if c == 0x1b:
            # read a short escape sequence if present
            b2=self.read_byte(0.03)
            if not b2: return ESC
            if b2 == b'[':
                seq=b''
                # read until a final byte
                for _ in range(8):
                    nb=self.read_byte(0.01)
                    if not nb: break
                    seq += nb
                    if 0x40 <= nb[0] <= 0x7e: break
                s=seq.decode('ascii','ignore')
                if s == 'A': return ARROW_UP
                if s == 'B': return ARROW_DOWN
                if s == 'C': return ARROW_RIGHT
                if s == 'D': return ARROW_LEFT
                if s in ('H','1~','7~'): return HOME
                if s in ('F','4~','8~'): return END
                if s == '3~': return DEL_KEY
                if s == '5~': return PAGE_UP
                if s == '6~': return PAGE_DOWN
                if s in ('1;5C','5C'): return CTRL_RIGHT
                if s in ('1;5D','5D'): return CTRL_LEFT
                if s in ('1;5A','5A'): return CTRL_UP
                if s in ('1;5B','5B'): return CTRL_DOWN
                if s in ('1;3C','3C'): return ALT_RIGHT
                if s in ('1;3D','3D'): return ALT_LEFT
                return UNKNOWN
            if b2 == b'O':
                b3=self.read_byte(0.01)
                if b3 == b'H': return HOME
                if b3 == b'F': return END
                return UNKNOWN
            try: ch=b2.decode('utf-8')
            except Exception: return UNKNOWN
            m={'f':ALT_F,'F':ALT_F,'b':ALT_B,'B':ALT_B,'n':ALT_N,'N':ALT_N,'p':ALT_P,'P':ALT_P,'x':ALT_X,'X':ALT_X,'v':ALT_V,'V':ALT_V,'<':ALT_LT,'>':ALT_GT}
            return m.get(ch, UNKNOWN)
        ctrl_map={
            1:CTRL_A,2:CTRL_B,4:CTRL_D,5:CTRL_E,6:CTRL_F,7:CTRL_G,8:CTRL_H,9:'\t',10:CTRL_J,11:CTRL_K,12:CTRL_L,13:CTRL_M,
            14:CTRL_N,15:CTRL_O,16:CTRL_P,17:CTRL_Q,18:CTRL_R,19:CTRL_S,21:CTRL_U,22:CTRL_V,23:CTRL_W,24:CTRL_X,27:ESC,29:CTRL_RBR,31:CTRL_US,
            127:CTRL_H,
        }
        if c in ctrl_map: return ctrl_map[c]
        if c >= 0x20:
            if c < 0x80:
                return chr(c)
            # utf-8 multibyte
            needed=0
            if (c & 0xE0)==0xC0: needed=1
            elif (c & 0xF0)==0xE0: needed=2
            elif (c & 0xF8)==0xF0: needed=3
            data=bytes([c])
            for _ in range(needed):
                nb=self.read_byte(0.05)
                if nb: data+=nb
            try: return data.decode('utf-8')
            except Exception: return UNKNOWN
        return UNKNOWN


class Editor:
    def __init__(self, term: Terminal, rows: int, cols: int, buffers: List[Buffer]):
        self.term=term; self.rows=rows; self.cols=cols; self.buffers=buffers; self.cur=0
        self.message="Ctrl-? for help"; self.message_time=time.time(); self.message_error=False
        self.running=True; self.quit_times=1
        self.search_query=None; self.search_matches=[]; self.search_current=-1
        self.full_redraw=True
        self.last_status_msg_visible=True

    @property
    def buf(self) -> Buffer:
        return self.buffers[self.cur]

    def set_message(self, msg: str, error: bool=False):
        self.message=msg; self.message_time=time.time(); self.message_error=error

    def clear_message(self):
        self.message=''; self.message_error=False

    def msg_visible(self) -> bool:
        return bool(self.message) and (time.time() - self.message_time < 5.0)

    def screen_rows(self) -> int:
        return self.rows - 1 - (1 if self.msg_visible() else 0)

    def update_window_size(self):
        try:
            data=fcntl.ioctl(sys.stdout.fileno(), termios.TIOCGWINSZ, struct.pack('HHHH',0,0,0,0))
            r,c,_,_=struct.unpack('HHHH',data)
            if r>=3 and c>=1:
                self.rows=r; self.cols=c
        except Exception:
            pass

    def scroll(self):
        b=self.buf; sr=max(1,self.screen_rows())
        b.clamp_cursor()
        rx=b.current_rx()
        if b.cy < b.rowoff: b.rowoff=b.cy
        if b.cy >= b.rowoff + sr: b.rowoff=b.cy - sr + 1
        if rx < b.coloff: b.coloff=rx
        if rx >= b.coloff + self.cols: b.coloff=rx - self.cols + 1
        if b.rowoff < 0: b.rowoff=0
        if b.coloff < 0: b.coloff=0

    def row_search_spans(self, filerow: int):
        if not self.search_query: return []
        spans=[]
        for idx,(y,a,b) in enumerate(self.search_matches):
            if y==filerow:
                spans.append((a,b, idx==self.search_current))
        return spans

    def render_line(self, row: str, syntax: str, filerow: int) -> str:
        colors=compute_syntax_colors(row, syntax)
        search_spans=self.row_search_spans(filerow)
        out=[]; rx=0; visible=0; cur_color=None; i=0
        def color_at(idx):
            for a,b,iscur in search_spans:
                if a <= idx < b:
                    return SEARCH_CUR if iscur else SEARCH_OTHER
            return colors[idx] if idx < len(colors) else None
        while i < len(row) and visible < self.cols:
            ch=row[i]
            w=char_width(ch, rx)
            # skip columns before horizontal offset
            if rx + w <= self.buf.coloff:
                rx += w; i+=1; continue
            if rx < self.buf.coloff:
                # partial wide/tab clipped: skip it
                rx += w; i+=1; continue
            if visible + w > self.cols:
                break
            col=color_at(i)
            if col != cur_color:
                out.append(col if col else RESET); cur_color=col
            if ch == '\t':
                out.append(' ' * w)
            else:
                out.append(ch)
            rx += w; visible += w; i+=1
        if cur_color:
            out.append(RESET)
        else:
            out.append(RESET)
        return ''.join(out)

    def draw_rows(self):
        b=self.buf; sr=max(1,self.screen_rows())
        for y in range(sr):
            filerow=b.rowoff+y
            cwrite(f"\x1b[{y+1}H")
            if filerow < len(b.rows):
                cwrite(self.render_line(b.rows[filerow], b.syntax, filerow))
                cwrite('\x1b[K')
            else:
                # special blank cursor line for a new unnamed buffer after interaction
                if (not b.rows) and b.empty_total_one and (not b.virgin) and filerow == 0:
                    cwrite(RESET+'\x1b[K')
                elif (not b.rows) and b.virgin and b.filename is None and y == sr//3:
                    msg=WELCOME
                    if str_width(msg) > self.cols:
                        msg=truncate_to_width(msg,self.cols)
                    padding=(self.cols - str_width(msg))//2
                    if padding>0:
                        cwrite('\x1b[37m~'+RESET)
                        padding-=1
                    if padding>0: cwrite(' '*padding)
                    cwrite(msg+'\x1b[K')
                else:
                    cwrite('\x1b[37m~'+RESET+'\x1b[K')
        cwrite(RESET)

    def draw_status_bar(self):
        b=self.buf; row=self.screen_rows()+1
        filename=b.filename if b.filename is not None else '[No Name]'
        left=f'"{filename}" - {self.cur+1}/{len(self.buffers)}'
        if b.dirty(): left += ' (modified)'
        right=f'{b.syntax} {b.cy+1}/{b.total_lines()}'
        if str_width(left) > self.cols:
            status=truncate_to_width(left,self.cols)
        elif str_width(left)+str_width(right) > self.cols:
            status=pad_to_width(left,self.cols)
        else:
            spaces=self.cols - str_width(left) - str_width(right)
            status=left + ' '*spaces + right
        status=pad_to_width(status,self.cols)
        cwrite(f"\x1b[{row}H\x1b[7m{status}\x1b[39;0m")

    def draw_message_bar(self):
        if not self.msg_visible(): return
        row=self.screen_rows()+2
        text=truncate_to_width(self.message,self.cols)
        cwrite(f"\x1b[{row}H")
        if self.message_error:
            cwrite('\x1b[97m\x1b[41m'+text+'\x1b[39;0m')
        else:
            cwrite(text)
        cwrite('\x1b[K')

    def refresh_screen(self):
        self.update_window_size()
        self.scroll()
        cwrite('\x1b[?25l')
        self.draw_rows()
        self.draw_status_bar()
        self.draw_message_bar()
        b=self.buf
        cy=b.cy-b.rowoff+1
        rx=b.current_rx(); cx=rx-b.coloff+1
        cy=max(1,min(self.rows,cy)); cx=max(1,min(self.cols,cx))
        cwrite(f"\x1b[{cy};{cx}H\x1b[?25h")

    def draw_help(self):
        sr=max(1,self.screen_rows())
        pad=max(0,(self.cols-66)//2)
        for i,(key,desc) in enumerate(MAPPINGS[:sr]):
            cwrite(f"\x1b[{i+1}H" + ' '*pad + '\x1b[96m' + f"{key:<30}" + RESET + f": {desc}" + '\x1b[K')

    def prompt(self, base: str, suffix: str, allow_empty: bool=True, cancel_message: bool=True) -> Optional[str]:
        b=''
        while True:
            self.set_message(base + b + suffix)
            self.refresh_screen()
            # cursor to prompt input position
            msgrow=self.screen_rows()+2
            pos=str_width(base+b)+1
            pos=max(1,min(self.cols,pos))
            cwrite(f"\x1b[{msgrow};{pos}H")
            k=self.term.read_key()
            if k in (CTRL_M,):
                if b=='' and not allow_empty:
                    self.clear_message(); self.refresh_screen(); return None
                return b
            if k in (CTRL_G, ESC):
                if cancel_message:
                    self.set_message('Canceled')
                    self.refresh_screen()
                else:
                    self.clear_message(); self.refresh_screen()
                return None
            if k in (CTRL_H, DEL_KEY):
                if b: b=b[:-1]
            elif isinstance(k,str) and len(k)==1 and (ord(k)>=32 or k=='\t'):
                b += k
            # ignore other keys

    def save_buffer(self):
        b=self.buf
        if b.filename is None:
            name=self.prompt('Save as: ', ' (^G or ESC to cancel)', allow_empty=False, cancel_message=False)
            if name is None:
                return
            b.filename=name; b.syntax=syntax_for_filename(name)
        try:
            if b.rows:
                data=('\n'.join(b.rows)+'\n').encode('utf-8')
            else:
                data=(b'\n' if b.empty_total_one else b'')
            with open(b.filename,'wb') as f:
                f.write(data)
            b.saved_pos=b.hist_pos
            self.set_message(f"{len(data)} bytes written to {b.filename}")
        except OSError as e:
            self.set_message(f"Could not save: {printable_error(e)}")
        self.refresh_screen()

    def open_buffer_prompt(self):
        name=self.prompt('Open: ', ' (Empty name for new text buffer, ^G or ESC to cancel)', allow_empty=True, cancel_message=True)
        if name is None:
            return
        if name == '':
            nb=Buffer(None, [''], empty_total_one=False, virgin=False)
        else:
            # fatal on bad open, as in the original
            nb=load_file(name)
        self.buffers.append(nb); self.cur=len(self.buffers)-1
        self.clear_message(); self.refresh_screen()

    def next_buffer(self, delta:int):
        if len(self.buffers)<=1:
            self.set_message('No other buffer is opened'); self.refresh_screen(); return
        self.cur=(self.cur+delta)%len(self.buffers)
        self.clear_message(); self.refresh_screen()

    def current_matches_from_cursor(self, query: str):
        b=self.buf; matches=find_all_matches(b.rows, query)
        cur=-1
        if matches:
            for idx,(y,a,_) in enumerate(matches):
                if y > b.cy or (y==b.cy and a >= b.cx):
                    cur=idx; break
            if cur<0: cur=0
        return matches,cur

    def apply_search_cursor(self):
        if 0 <= self.search_current < len(self.search_matches):
            y,a,_=self.search_matches[self.search_current]
            self.buf.cy=y; self.buf.cx=a

    def search_prompt(self):
        b=self.buf
        orig=(b.cx,b.cy,b.rowoff,b.coloff)
        query=''
        self.search_query=''; self.search_matches=[]; self.search_current=-1
        suffix=' (^F or ^N or RIGHT to forward, ^B or ^P or LEFT to back, ^G or ESC to cancel)'
        while True:
            self.set_message('Search: ' + query + suffix)
            self.refresh_screen()
            msgrow=self.screen_rows()+2; pos=str_width('Search: '+query)+1
            cwrite(f"\x1b[{msgrow};{max(1,min(self.cols,pos))}H")
            k=self.term.read_key()
            if k == CTRL_M:
                self.search_query=None; self.search_matches=[]
                if query and self.search_current>=0:
                    self.set_message('Found')
                else:
                    b.cx,b.cy,b.rowoff,b.coloff=orig
                    self.set_message('Not found')
                self.refresh_screen(); return
            if k in (CTRL_G, ESC):
                self.search_query=None; self.search_matches=[]
                b.cx,b.cy,b.rowoff,b.coloff=orig
                self.set_message('Canceled'); self.refresh_screen(); return
            if k in (CTRL_H, DEL_KEY):
                if query: query=query[:-1]
                b.cx,b.cy,b.rowoff,b.coloff=orig
            elif k in (CTRL_N, CTRL_F, ARROW_RIGHT):
                if self.search_matches:
                    self.search_current=(self.search_current+1)%len(self.search_matches)
                    self.apply_search_cursor()
                continue
            elif k in (CTRL_P, CTRL_B, ARROW_LEFT):
                if self.search_matches:
                    self.search_current=(self.search_current-1)%len(self.search_matches)
                    self.apply_search_cursor()
                continue
            elif isinstance(k,str) and len(k)==1 and ord(k)>=32:
                query += k
                b.cx,b.cy,b.rowoff,b.coloff=orig
            else:
                continue
            self.search_query=query if query else None
            self.search_matches,self.search_current=self.current_matches_from_cursor(query)
            if self.search_current>=0: self.apply_search_cursor()

    def page_move(self, direction:int):
        for _ in range(max(1,self.screen_rows())):
            if direction>0: self.buf.move_down()
            else: self.buf.move_up()
        self.refresh_screen()

    def handle_key(self,k):
        if k != CTRL_Q:
            self.quit_times=1
        b=self.buf
        try:
            if k == CTRL_Q:
                if any(buf.dirty() for buf in self.buffers) and self.quit_times>0:
                    self.set_message('At least one file has unsaved changes! Press ^Q again to quit or ^S to save', True)
                    self.quit_times-=1; self.refresh_screen(); return
                self.running=False; return
            elif k == CTRL_S:
                self.save_buffer(); return
            elif k == CTRL_O:
                self.open_buffer_prompt(); return
            elif k == CTRL_X:
                self.next_buffer(1); return
            elif k == ALT_X:
                self.next_buffer(-1); return
            elif k in (CTRL_P, ARROW_UP): b.move_up()
            elif k in (CTRL_N, ARROW_DOWN): b.move_down()
            elif k in (CTRL_F, ARROW_RIGHT): b.move_right()
            elif k in (CTRL_B, ARROW_LEFT): b.move_left()
            elif k in (CTRL_A, HOME, ALT_LEFT): b.move_home()
            elif k in (CTRL_E, END, ALT_RIGHT): b.move_end()
            elif k in (CTRL_V, ESC, PAGE_DOWN):
                if k == ESC:
                    # a bare Ctrl-[ is page down in this editor
                    self.page_move(1); return
                self.page_move(1); return
            elif k in (CTRL_RBR, ALT_V, PAGE_UP): self.page_move(-1); return
            elif k in (ALT_F, CTRL_RIGHT): b.move_next_word()
            elif k in (ALT_B, CTRL_LEFT): b.move_prev_word()
            elif k in (ALT_N, CTRL_DOWN): b.move_next_paragraph()
            elif k in (ALT_P, CTRL_UP): b.move_prev_paragraph()
            elif k == ALT_LT: b.move_top()
            elif k == ALT_GT: b.move_bottom()
            elif k == CTRL_H: b.backspace()
            elif k == CTRL_D or k == DEL_KEY: b.delete_forward()
            elif k == CTRL_W: b.delete_word()
            elif k == CTRL_J: b.delete_to_bol()
            elif k == CTRL_K: b.delete_to_eol()
            elif k == CTRL_U:
                if not b.undo(): self.set_message('No older change')
            elif k == CTRL_R:
                if not b.redo(): self.set_message('Buffer is already newest')
            elif k == CTRL_G:
                self.search_prompt(); return
            elif k == CTRL_M:
                b.insert_newline()
            elif k == CTRL_L:
                self.clear_message(); b.virgin=False; self.refresh_screen(); return
            elif k == CTRL_US:
                self.draw_help(); return
            elif isinstance(k,str) and len(k)==1 and (ord(k)>=32 or k=='\t'):
                b.insert_char(k)
            else:
                return
            self.refresh_screen()
        except Exception:
            raise

    def loop(self):
        self.refresh_screen()
        while self.running:
            k=self.term.read_key()
            self.handle_key(k)


def parse_args(argv: List[str]):
    help_flag=False; version_flag=False; files=[]; stop=False
    for arg in argv[1:]:
        if stop:
            files.append(arg); continue
        if arg == '--':
            stop=True; continue
        if arg.startswith('--') and len(arg)>2:
            body=arg[2:]
            name=body.split('=',1)[0]
            has_eq='=' in body
            if name == 'help':
                if has_eq: return ('error', "Option 'help' does not take an argument. Please see --help for more details")
                help_flag=True
            elif name == 'version':
                if has_eq: return ('error', "Option 'version' does not take an argument. Please see --help for more details")
                version_flag=True
            else:
                return ('error', f"Unrecognized option: '{name}'. Please see --help for more details")
        elif arg.startswith('-') and arg != '-':
            for ch in arg[1:]:
                if ch == 'h': help_flag=True
                elif ch == 'v': version_flag=True
                else: return ('error', f"Unrecognized option: '{ch}'. Please see --help for more details")
        else:
            files.append(arg)
    if version_flag: return ('version', files)
    if help_flag: return ('help', files)
    return ('run', files)


def print_help(prog: str):
    lines=''
    for key,desc in MAPPINGS:
        lines += f"    {key:<30} : {desc}\n"
    sys.stdout.write(HELP_TEMPLATE.format(prog=prog, mappings=lines))


def main(argv=None):
    if argv is None: argv=sys.argv
    mode=parse_args(argv)
    if mode[0]=='error':
        sys.stderr.write('Error: '+mode[1]+'\n'); return 1
    if mode[0]=='version':
        sys.stdout.write(VERSION+'\n'); return 0
    if mode[0]=='help':
        print_help(argv[0]); return 0
    files=mode[1]
    term=Terminal()
    try:
        rows,cols=term.setup()
    except RuntimeError as e:
        sys.stderr.write('Error: '+str(e)+'\n'); return 1
    except OSError as e:
        sys.stderr.write('Error: '+printable_error(e)+'\n'); return 1
    term.enable_raw()
    term.enter_alt()
    try:
        buffers=[]
        if files:
            for path in files:
                buffers.append(load_file(path))
        else:
            buffers=[Buffer(None, [], empty_total_one=True, virgin=True)]
        ed=Editor(term, rows, cols, buffers)
        ed.loop()
        term.leave_alt(); term.restore(); return 0
    except Exception as e:
        term.leave_alt(); term.restore()
        sys.stderr.write('Error: '+printable_error(e)+'\n')
        return 1
    finally:
        term.restore()

if __name__ == '__main__':
    sys.exit(main())
